
fn cancel_unpublished<M:Mode>(){
 let mut bank=Bank::new(false);let mut observer=|_|true;let mut native=NativeDecodeControl::new(1<<20,&mut observer);let mut frame=NativeReceivingEffect::default();let mut producer=OriginalEffectAuthority::new(Commands::<M>{source:bank.source.clone(),mode:PhantomData});let mut slots=Slots::<M>::default();let mut input=Some(73);let d=Slots::<M>::capture_demand().unwrap();let work=slots.capture_work_demand(&input).unwrap();complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,work,Command::Capture(&mut slots,&mut input))).result.unwrap();
 complete(bank.run(&mut native,|native|M::advance(&mut slots,native)).unwrap()).result.unwrap();assert!(!slots.output_ready());assert_eq!(slots.input(),Some(&73));assert!(bank.wallet.lock().unwrap().spent.retained_capacity_bytes>0);
 let mut returned=None;for _ in 0..12{let d=slots.reclaim_input_demand().unwrap();let turn=complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,1,Command::Reclaim(&mut slots,&mut returned)));if turn.result.is_ok(){break}let d=slots.close_demand(4096).unwrap();let work=slots.close_work_demand(4096).unwrap();complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,work,Command::Close(&mut slots))).result.unwrap();}
 assert_eq!(returned,Some(73));for _ in 0..4{if slots.terminal_is_empty(){break}let d=slots.close_demand(4096).unwrap();let work=slots.close_work_demand(4096).unwrap();complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,work,Command::Close(&mut slots))).result.unwrap();}assert!(slots.terminal_is_empty());let wallet=bank.wallet.lock().unwrap();assert_eq!(wallet.spent.retained_capacity_bytes,wallet.spent.released_bytes);assert_eq!(256-wallet.fuel,native.actual_work());drop(wallet);assert!(producer.into_producer().is_ok());
}
#[test]fn actual_arc_unpublished_birth_cancels_and_returns_the_original_input(){cancel_unpublished::<ArcMode>()}
#[test]fn actual_sealed_unpublished_birth_cancels_and_returns_the_original_input(){cancel_unpublished::<SealedMode>()}
#[test]fn actual_constructor_rejects_foreign_source_before_action_and_header_clear(){
 let mut bank=Bank::new(false);let mut foreign=Bank::new(false);let mut observer=|_|true;let mut native=NativeDecodeControl::new(1<<20,&mut observer);let mut frame=NativeReceivingEffect::default();let mut producer=OriginalEffectAuthority::new(Commands::<ArcMode>{source:bank.source.clone(),mode:PhantomData});let mut foreign_frame=NativeReceivingEffect::default();let mut foreign_producer=OriginalEffectAuthority::new(Commands::<ArcMode>{source:foreign.source.clone(),mode:PhantomData});let mut slots=Slots::<ArcMode>::default();let mut input=Some(73);let d=Slots::<ArcMode>::capture_demand().unwrap();let work=slots.capture_work_demand(&input).unwrap();complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,work,Command::Capture(&mut slots,&mut input))).result.unwrap();
 let before=foreign.wallet.lock().unwrap().fuel;assert!(foreign.run(&mut native,|native|ArcMode::advance(&mut slots,native)).is_err());assert_eq!(foreign.wallet.lock().unwrap().fuel,before);assert_eq!(slots.input(),Some(&73));assert!(!slots.advance_pending());
 for _ in 0..4{if slots.output_ready(){break}complete(bank.run(&mut native,|native|ArcMode::advance(&mut slots,native)).unwrap()).result.unwrap();}assert!(slots.output_ready());let mut output=None;let d=ArcMode::take_demand(&slots).unwrap();complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,1,Command::Take(&mut slots,&mut output))).result.unwrap();
 let d=slots.close_demand(4096).unwrap();let work=slots.close_work_demand(4096).unwrap();let denied=complete(command(&mut foreign,&mut native,&mut foreign_frame,&mut foreign_producer,d,work,Command::Close(&mut slots)));assert!(denied.result.is_err());assert!(!slots.terminal_is_empty());
 complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,work,Command::Close(&mut slots))).result.unwrap();let d=slots.close_demand(4096).unwrap();let work=slots.close_work_demand(4096).unwrap();let denied=complete(command(&mut foreign,&mut native,&mut foreign_frame,&mut foreign_producer,d,work,Command::Close(&mut slots)));assert!(denied.result.is_err());assert!(!slots.terminal_is_empty());complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,work,Command::Close(&mut slots))).result.unwrap();assert!(slots.terminal_is_empty());
 let(mut owner,mut value)=(None,None);let(d,work)=ArcMode::consume_demand(&output,&owner).unwrap();complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,work,Command::Consume(&mut output,&mut owner,&mut value))).result.unwrap();assert_eq!(value,Some(73));assert!(producer.into_producer().is_ok());assert!(foreign_producer.into_producer().is_ok());
}
